"use strict";

const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const files = [
  ...Array.from({ length: 8 }, (_, bank) => `src/bank${bank}.asm`),
  "src/engine.asm",
  "src/boot.asm",
  "src/splash.asm",
  "src/tiny_font.inc",
  "lib/vcs.h",
  "lib/macro.h",
  "lib/xmacro.h",
];

const sources = Object.fromEntries(files.map((name) => [
  name,
  fs.readFileSync(path.join(root, ...name.split("/")), "utf8"),
]));
const output = `// Generated by tools/build_browser_source_bundle.js.\nwindow.TextAdventureSourceFiles = Object.freeze(${JSON.stringify(sources)});\n`;
fs.writeFileSync(path.join(root, "editor", "source_bundle.js"), output, "utf8");
console.log(`Bundled ${files.length} browser assembly source files.`);
